"""Exchange rates from the provider."""

from app import settings

_cache: dict[str, float] = {}


def fetch_rate(currency: str) -> float:
    """One billed call to the rates provider (stubbed here)."""
    return {"EUR": 1.08, "GBP": 1.27, "USD": 1.0}[currency]


def rate(currency: str) -> float:
    if settings.RATE_CACHE:
        if currency not in _cache:
            _cache[currency] = fetch_rate(currency)
        return _cache[currency]
    return fetch_rate(currency)

