from app.invoice import total_usd


def test_euros():
    assert total_usd([("EUR", 100.0)]) == 108.0


def test_mixed():
    assert total_usd([("USD", 1.0), ("EUR", 1.0), ("GBP", 1.0)]) == 3.35

